import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-quote-panel';
  group.position.set(1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 2.2;
  const height = 1.375;

  // Background plane
  const geometry = new THREE.PlaneGeometry(width, height);
  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;

  const material = new THREE.MeshBasicNodeMaterial();
  const uvNode = uv();
  const texNode = texture(tex, uvNode);
  const tint = vec4(color(0x16161d), 1.0);
  material.colorNode = texNode.mul(vec4(0.9, 0.9, 0.92, 1.0)).add(tint.mul(0.05));
  material.transparent = true;

  const panel = new THREE.Mesh(geometry, material);
  panel.name = 'quote-panel-bg';
  group.add(panel);

  // Accent edge frame (thin border plane behind, slightly larger, accent color)
  const edgeGeo = new THREE.PlaneGeometry(width + 0.04, height + 0.04);
  const edgeMat = new THREE.MeshBasicNodeMaterial();
  edgeMat.colorNode = vec4(color(0xff2a38), 1.0);
  edgeMat.transparent = true;
  edgeMat.opacity = 0.0;
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.001;
  edge.name = 'quote-panel-edge';
  group.add(edge);

  // Quote text
  const quoteText = ctx.fontAtlas.createText({
    text: '"The atelier reshaped how we think about a timepiece — precision made human."',
    font: 'display',
    weight: 400,
    size: 0.13,
    color: '#e8ecf2',
    maxWidth: width - 0.5,
    align: 'left',
  });
  quoteText.position.set(-width / 2 + 0.25, height / 2 - 0.35, 0.01);
  group.add(quoteText);

  // Attribution line
  const attributionText = ctx.fontAtlas.createText({
    text: '— M. Sorel, Head of Product',
    font: 'text',
    weight: 700,
    size: 0.09,
    color: '#ff2a38',
    maxWidth: width - 0.5,
    align: 'left',
  });
  attributionText.position.set(-width / 2 + 0.25, -height / 2 + 0.25, 0.01);
  group.add(attributionText);

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(group, primitive.params || {});
      }
    });
  }

  // Animation state
  const baseY = group.position.y;
  const baseScale = { x: 1, y: 1, z: 1 };
  let hoverTween = null;
  let pressTween = null;

  const onHover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      }, 0)
      .to(edgeMat, {
        opacity: 0.6,
        duration: 0.3,
        ease: 'power2.out',
      }, 0);
  };

  const onHoverEnd = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      }, 0)
      .to(edgeMat, {
        opacity: 0.0,
        duration: 0.3,
        ease: 'power2.out',
      }, 0);
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      })
      .to(group.scale, {
        x: baseScale.x,
        y: baseScale.y,
        z: baseScale.z,
        duration: 0.2,
        ease: 'power2.out',
      });

    if (ctx.emit) {
      ctx.emit('hub-pricing.select', { source: group.name });
    }
  };

  group.userData.handlers = {
    onPointerOver: onHover,
    onPointerOut: onHoverEnd,
    onPointerDown: onClick,
    onClick: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);

    geometry.dispose();
    material.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    if (tex) tex.dispose();

    if (quoteText.geometry) quoteText.geometry.dispose();
    if (quoteText.material) quoteText.material.dispose();
    if (attributionText.geometry) attributionText.geometry.dispose();
    if (attributionText.material) attributionText.material.dispose();
  };

  return group;
}
